  ('lib-gipsy-research-100langkah-001', '101', 1, 'Gipsy Research', 'Peta Riset Sistematis dari Nol sampai Sidang', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Skripsi molor itu bukan karena kamu males. Tapi karena nggak ada yang ngatur urutan kerjanya."}, {"scene": "Body — kalimat 1", "script": "Banyak mahasiswa pinter tapi bingung mulai dari mana, terus malah kelamaan mikir."}, {"scene": "Body — kalimat 2", "script": "100 Langkah dari Gipsy Research ngubah itu — seluruh proses skripsi dipecah jadi 10 fase."}, {"scene": "Body — kalimat 3", "script": "Tiap fase punya langkah-langkah kecil yang saling nyambung dan jelas output-nya."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu nggak perlu nebak lagi — semuanya tinggal dikikutin, satu per satu."}, {"scene": "Body — kalimat 5", "script": "Bukan jalan pintas, tapi peta yang nuntun kamu dari awal sampai tahap akhir."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-002', '102', 2, 'Gipsy Research', 'Fase 1 Penemuan Ide — Mulai Skripsi Tanpa Bingung', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Mulai skripsi itu sering jadi bagian paling susah. Bukan nulisnya, tapi mutusin mau ngapain dulu."}, {"scene": "Body — kalimat 1", "script": "Topik bolak-balik, dosen revisi, proposal molor — semua karena nggak ada urutan yang ngerti."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, fase pertama khusus ngebantu kamu nemuin ide dan topik."}, {"scene": "Body — kalimat 3", "script": "Ada tools AI yang ngebantu brainstorm, worksheet yang ngarahin eksplorasi, dan quiz yang ngecek arah."}, {"scene": "Body — kalimat 4", "script": "Setelah fase 1 selesai, kamu udah punya topik yang matang dan siap dijadiin proposal."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu nggak lagi stuck di “mau mulai dari mana” — semuanya udah jelas dari awal."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-003', '103', 3, 'Gipsy Research', 'Bab 1 Kokoh — Fondasi Skripsi yang Nggak Direvisi Berulang', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Bab 1 itu kayak pintu masuk. Kalau fondasinya rapuh, bab 2, 3, 4 bakal ikut-ikutan roboh."}, {"scene": "Body — kalimat 1", "script": "Banyak yang bab 1-nya direvisi puluhan kali karena latar belakang, rumusan masalah, sama tujuannya nggak nyambung."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research punya Fase 3 khusus buat Konstruksi Masalah dan Pendahuluan."}, {"scene": "Body — kalimat 3", "script": "Kamu dapet worksheet, video materi, dan AI yang ngebantu ngerangkai logika bab 1."}, {"scene": "Body — kalimat 4", "script": "Tiap langkah ada output yang jelas — jadi kamu tau kapan bab 1 kamu udah cukup kuat buat lanjut."}, {"scene": "Body — kalimat 5", "script": "Setelah fase ini kelar, bab 1 kamu bukan cuma kelar — tapi beneran jadi fondasi yang kuat."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-004', '104', 4, 'Gipsy Research', 'Cari Jurnal Lebih Relevan dengan 250 Juta+ Artikel', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Cari jurnal itu makan waktu. Belum lagi kalau dapat yang nggak relevan sama topik."}, {"scene": "Body — kalimat 1", "script": "Kebanyakan mahasiswa ngabisin waktu googling, buka-situs satu-satu, nyatet manual."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research nyediain Pencari Artikel Ilmiah PRO — akses 250 juta+ artikel terindeks."}, {"scene": "Body — kalimat 3", "script": "Tinggal masukin kata kunci, langsung dapet rangkuman dan link ke artikel asli."}, {"scene": "Body — kalimat 4", "script": "Plus di Fase 2, kamu juga diajarin cara nyusun strategi pencarian yang tepat."}, {"scene": "Body — kalimat 5", "script": "Jadi literatur kamu nggak cuma banyak — tapi juga relevan dan siap dipake di bab kamu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-005', '105', 5, 'Gipsy Research', 'Pilih Metode Penelitian yang Cocok — Bukan Asal Pilih', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Metode penelitian itu banyak. Kualitatif, kuantitatif, mixed method — bingung pilih yang mana."}, {"scene": "Body — kalimat 1", "script": "Salah pilih metode bisa bikin dosen revisi, bahkan ganti dari awal pas sidang."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research punya Fase 5 yang khusus ngebantu kamu nentuin Desain Metodologi."}, {"scene": "Body — kalimat 3", "script": "Kamu dapet worksheet yang ngarahin eksplorasi metode, plus video yang ngejelasin kapan pake yang mana."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu bisa pilih metode yang pas sama topik, bukan karena ikut-ikutan."}, {"scene": "Body — kalimat 5", "script": "Dan setelah desain kelar, kamu tinggal lanjut ke tahap Pengembangan Instrumen di fase selanjutnya."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-006', '106', 6, 'Gipsy Research', 'Standar Skripsi yang Jelas — Buat Kamu dan Dosen', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Dosen strict itu bukan masalah. Masalahnya kalau kamu nggak tau standar yang dia mau."}, {"scene": "Body — kalimat 1", "script": "Banyak mahasiswa kebingungan karena beda dosen, beda standar — dan nggak ada yang ngasih tau dari awal."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, semua fase udah punya guideline yang jelas."}, {"scene": "Body — kalimat 3", "script": "Mulai dari cara nyusun latar belakang, format sitasi, sampe struktur argumen yang biasa diterima dosen."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu bisa ngerjain lebih pede, tanpa nebak-nebak lagi."}, {"scene": "Body — kalimat 5", "script": "Dan kalau draft kamu tetep butuh second opinion, ada fitur Review Draft dari mentor yang siap bantu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-007', '107', 7, 'Gipsy Research', 'Nggak Sendirian — Ada Mentor dan Komunitas yang Nemenin', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Ngerjain skripsi tuh berat. Tapi bukan berarti kamu harus ngerjainnya sendirian."}, {"scene": "Body — kalimat 1", "script": "Kebanyakan mahasiswa ngerasa sendirian karena nggak tau mau tanya ke siapa atau diskusi sama siapa."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research nyiapin lebih dari sekedar materi — ada mentor dan Review Draft Penelitian."}, {"scene": "Body — kalimat 3", "script": "Mulai dari Review Draft yang dikerjain mentor berpengalaman."}, {"scene": "Body — kalimat 4", "script": "Sampe 10+ kelas online yang ngebolehin kamu belajar dan diskusi bareng-bareng."}, {"scene": "Body — kalimat 5", "script": "Jadi prosesnya tetep di tangan kamu, tapi kamu nggak jalan tanpa pendampingan."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-008', '108', 8, 'Gipsy Research', 'Persiapan Sidang yang Mateng — Bukan Lompatan Tiba-tiba', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Takut sidang itu wajar. Tapi biasanya datang dari persiapan yang kurang kebayang."}, {"scene": "Body — kalimat 1", "script": "Banyak yang grogi karena nggak tau apa yang bakal ditanyain, atau nggak yakin sama isi skripsinya sendiri."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research punya Fase 10 khusus buat Persiapan Sidang."}, {"scene": "Body — kalimat 3", "script": "Ada checklist apa aja yang perlu disiapkan, template materi presentasi, sampe kumpulan pertanyaan yang sering ditanyain dosen."}, {"scene": "Body — kalimat 4", "script": "Plus Review Draft Penelitian yang ngebantu kamu yakin sama isi skripsi kamu sendiri."}, {"scene": "Body — kalimat 5", "script": "Jadi pas hari sidang, kamu udah ngelewatin seluruh prosesnya — bukan lompatan tiba-tiba."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-009', '109', 9, 'Gipsy Research', 'Konsisten Ngerjain — Sistem yang Ngurangin Overwhelm', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Konsisten itu sulit, apalagi kalau ngerjain skripsi tanpa sistem."}, {"scene": "Body — kalimat 1", "script": "Hari ini semangat, besok males, lusa bingung lagi — dan akhirnya molor berbulan-bulan."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research ngubah skripsi dari proyek raksasa jadi langkah-langkah kecil yang bisa dikerjain rutin."}, {"scene": "Body — kalimat 3", "script": "Tiap hari, kamu cuma perlu fokus di satu atau dua langkah, bukan ngerjain semuanya sekaligus."}, {"scene": "Body — kalimat 4", "script": "Plus ada quiz dan worksheet yang ngecek progres kamu di tiap fase."}, {"scene": "Body — kalimat 5", "script": "Jadi ritme kerjamu lebih kebawa — bukan ngebut di awal terus stuck di tengah."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-010', '110', 10, 'Gipsy Research', 'Ngurangin Overwhelm — Pecah Jadi Langkah Kecil', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Overwhelm itu tanda kamu ngerjain semuanya sekaligus. Bukan berarti kamu nggak bisa."}, {"scene": "Body — kalimat 1", "script": "Skripsi itu kompleks — bab 1, 2, 3, bab 4, bab 5, sidang — semua nimbun di kepala."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research mecah itu jadi 10 fase, dan tiap fase jadi beberapa langkah kecil."}, {"scene": "Body — kalimat 3", "script": "Jadi kamu nggak perlu mikir “skripsi” sekaligus — cukup fokus ke langkah yang lagi di depan."}, {"scene": "Body — kalimat 4", "script": "Tiap langkah ada output-nya sendiri, dan output itu ngejadiin pondasi buat langkah selanjutnya."}, {"scene": "Body — kalimat 5", "script": "Hasilnya, ngerjain skripsi kerasa kayak ngikutin rute — bukan naik gunung sendirian tanpa peta."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-011', '111', 11, 'Gipsy Research', 'Format Skripsi yang Nggak Bikin Pusing', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Format skripsi itu sering bikin pusing. Mulai dari cover, daftar isi, sampe daftar pustaka."}, {"scene": "Body — kalimat 1", "script": "Beda kampus, beda standar. Beda dosen pembimbing, beda lagi ekspektasinya."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, kamu dapet 20+ template yang udah disusun sesuai standar umum akademik."}, {"scene": "Body — kalimat 3", "script": "Mulai dari template Bab 1, Bab 2, Bab 3, sampe checklist sidang."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu bisa langsung ngerjain isinya — tanpa harus pusing format dari nol."}, {"scene": "Body — kalimat 5", "script": "Dan kalau kampus kamu punya standar spesifik, tinggal disesuaikan dari template yang udah ada."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-012', '112', 12, 'Gipsy Research', 'Latar Belakang yang Lebih Kuat dan Banyak Sumber', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Referensi kurang itu sering bikin bab 1 kamu keliatan tipis."}, {"scene": "Body — kalimat 1", "script": "Banyak yang latar belakangnya cuma 2-3 paragraf karena sumbernya dikit."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, kamu dapet akses ke Pencari Artikel Ilmiah PRO."}, {"scene": "Body — kalimat 3", "script": "250 juta+ artikel terindeks yang bisa langsung kamu cari berdasarkan kata kunci."}, {"scene": "Body — kalimat 4", "script": "Tiap artikel ada rangkuman singkatnya — jadi kamu nggak perlu baca satu-satu dulu."}, {"scene": "Body — kalimat 5", "script": "Hasilnya, latar belakang kamu bisa lebih kuat dan banyak sumber — bukan monoton."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-013', '113', 13, 'Gipsy Research', 'Paham Metode Penelitian — Bukan Cuma Pilih', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Bingung bedanya penelitian kualitatif dan kuantitatif? Itu bukan masalah — masalahnya kalau kamu nggak tau posisi kamu di mana."}, {"scene": "Body — kalimat 1", "script": "Metode itu alat, bukan harga mati. Yang penting kamu tau kenapa pilih salah satu."}, {"scene": "Body — kalimat 2", "script": "Di Fase 5 100 Langkah Gipsy Research, ada panduan lengkap soal Desain Metodologi Penelitian."}, {"scene": "Body — kalimat 3", "script": "Mulai dari jenis data, teknik sampling, sampe analisis yang cocok — semua dijelasin perbandingannya."}, {"scene": "Body — kalimat 4", "script": "Kamu juga dapet worksheet yang ngebantu kamu nentuin pilihan berdasarkan topik kamu."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu nggak cuma “milih” — tapi beneran paham kenapa metode itu cocok buat riset kamu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-014', '114', 14, 'Gipsy Research', 'Data yang Cukup dan Tertata dengan Baik', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Data nggak cukup itu sering bikin analisis kamu lemah."}, {"scene": "Body — kalimat 1", "script": "Apalagi kalau metode kamu butuh data primer, dan kamu belum tau mau ambil dari mana."}, {"scene": "Body — kalimat 2", "script": "Di Fase 7 100 Langkah Gipsy Research, ada panduan lengkap buat Pengumpulan & Manajemen Data."}, {"scene": "Body — kalimat 3", "script": "Mulai dari teknik sampling, cara distribusi kuesioner, sampe tools yang ngebantu ngatur data."}, {"scene": "Body — kalimat 4", "script": "Tiap langkah ada template dan worksheet yang siap dipake."}, {"scene": "Body — kalimat 5", "script": "Jadi data kamu nggak cuma terkumpul — tapi juga tertata dan siap diolah di fase selanjutnya."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-015', '115', 15, 'Gipsy Research', 'Argumen yang Nggak Lagi Kedengeran Kayak Daftar Fakta', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Nulis argumen yang kuat tuh beda sama nulis deskripsi. Banyak yang bab 4-nya kedengeran kayak daftar fakta."}, {"scene": "Body — kalimat 1", "script": "Padahal analisis itu harus nyambung, logis, dan ngedukung klaim kamu."}, {"scene": "Body — kalimat 2", "script": "Di Fase 9 100 Langkah Gipsy Research, kamu diajarin cara nyusun Pembahasan, Kesimpulan, sama Saran."}, {"scene": "Body — kalimat 3", "script": "Ada template dan contoh yang nunjukin gimana ngubah data mentah jadi argumen yang nyambung."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngebantu kamu nyusun alur logika pembahasan kamu."}, {"scene": "Body — kalimat 5", "script": "Jadi bab 4 kamu nggak cuma ngasih hasil — tapi juga jawab rumusan masalah yang diawal."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-016', '116', 16, 'Gipsy Research', 'Referensi Up-to-date — Bukan yang Outdated', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Referensi 10 tahun lalu? Itu salah satu alasan skripsi kamu dibilang outdated."}, {"scene": "Body — kalimat 1", "script": "Riset berkembang cepet, dan dosen biasanya ngeharap kamu pake sumber yang relatif baru."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, Pencari Artikel Ilmiah PRO nyediain artikel-artikel terbaru yang terindeks."}, {"scene": "Body — kalimat 3", "script": "Tinggal filter berdasarkan tahun, dan kamu langsung dapet sumber yang relevan sama waktu kamu."}, {"scene": "Body — kalimat 4", "script": "Plus di Fase 2, kamu diajarin cara ngecek tahun publikasi dan bobot sumbernya."}, {"scene": "Body — kalimat 5", "script": "Jadi referensi kamu bukan cuma banyak — tapi juga up-to-date dan kuat secara akademik."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-017', '117', 17, 'Gipsy Research', 'Visualisasi Data yang Tepat — Bukan Asal Bikin Grafik', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Visualisasi data itu bukan cuma biar bagus. Tapi biar pembacaan analisismu lebih cepet dan jelas."}, {"scene": "Body — kalimat 1", "script": "Banyak yang asal bikin grafik tanpa tau chart apa yang cocok buat datanya."}, {"scene": "Body — kalimat 2", "script": "Di Fase 8 100 Langkah Gipsy Research, ada panduan lengkap buat Olah Data & Analisis Hasil."}, {"scene": "Body — kalimat 3", "script": "Mulai dari cara milih jenis visualisasi, sampe tools AI yang bisa langsung bikinin chart yang tepat."}, {"scene": "Body — kalimat 4", "script": "Tiap chart yang dibikin langsung didasarin sama data kamu — bukan template kosong."}, {"scene": "Body — kalimat 5", "script": "Jadi bagian analisis kamu bukan cuma data — tapi juga visual yang ngekuatin narasi kamu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-018', '118', 18, 'Gipsy Research', 'Hipotesis yang Jadi Kompas — Bukan Formalitas', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Hipotesis itu sering dianggap formalitas. Padahal itu yang ngarahin seluruh penelitian kamu."}, {"scene": "Body — kalimat 1", "script": "Hipotesis yang asal bikin biasanya bikin penelitian kamu nggak fokus."}, {"scene": "Body — kalimat 2", "script": "Di Fase 4 100 Langkah Gipsy Research, kamu diajarin cara ngebangun Landasan Teori & Hipotesis."}, {"scene": "Body — kalimat 3", "script": "Mulai dari cara nyusun variabel, nyari teori yang relevan, sampe nyusun hipotesis yang bisa diuji."}, {"scene": "Body — kalimat 4", "script": "Kamu dapet worksheet yang ngebantu kamu ngecek hipotesis kamu logis apa nggak."}, {"scene": "Body — kalimat 5", "script": "Jadi hipotesis kamu bukan cuma tulisan — tapi beneran jadi kompas yang ngarahin riset kamu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-019', '119', 19, 'Gipsy Research', 'Overview 100 Langkah — Peta Lengkap dari Awal sampai Akhir', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Skripsi itu panjang. Tapi bukan berarti harus jalan tanpa rute."}, {"scene": "Body — kalimat 1", "script": "100 Langkah dari Gipsy Research adalah program yang ngubah seluruh proses skripsi jadi urutan yang jelas."}, {"scene": "Body — kalimat 2", "script": "Total ada 10 fase — dari Penemuan Ide, Penelusuran Literatur, Konstruksi Masalah, sampai Persiapan Sidang."}, {"scene": "Body — kalimat 3", "script": "Tiap fase dipecah lagi jadi beberapa langkah kecil yang saling nyambung."}, {"scene": "Body — kalimat 4", "script": "Tiap langkah punya paket: video materi, worksheet, AI tools, dan quiz evaluasi."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu nggak perlu nebak lagi — semuanya udah ada alur yang tinggal dikikutin."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-020', '120', 20, 'Gipsy Research', '10 Fase Sistematis yang Ngecover Seluruh Riset', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Riset itu kompleks. Tapi kalau dipotong-potong, semuanya jadi manageable."}, {"scene": "Body — kalimat 1", "script": "100 Langkah Gipsy Research bagi seluruh perjalanan skripsi jadi 10 fase."}, {"scene": "Body — kalimat 2", "script": "Fase 1 sampai 10 ngecover dari awal mikir topik, cari jurnal, susun bab 1, olah data, sampe siap sidang."}, {"scene": "Body — kalimat 3", "script": "Tiap fase punya langkah-langkah yang jelas output-nya."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu selalu tau lagi di mana, dan selanjutnya mau kemana."}, {"scene": "Body — kalimat 5", "script": "Bukan buat ngerjain skripsimu — tapi buat ngarahin kamu selama ngerjainnya."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-021', '121', 21, 'Gipsy Research', 'Fase 1 — Penemuan Ide dan Topik', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Topik yang kuat itu pondasi skripsi yang kuat."}, {"scene": "Body — kalimat 1", "script": "Fase 1 dari 100 Langkah Gipsy Research khusus ngebantu kamu nemuin dan matengin ide."}, {"scene": "Body — kalimat 2", "script": "Kamu dapet worksheet yang ngarahin eksplorasi topik dari berbagai sudut pandang."}, {"scene": "Body — kalimat 3", "script": "Ada juga tools AI yang ngebantu kamu brainstorm dan evaluasi kelayakan topik."}, {"scene": "Body — kalimat 4", "script": "Plus video materi yang nunjukin contoh topik yang lolos dan yang nggak."}, {"scene": "Body — kalimat 5", "script": "Setelah fase ini selesai, kamu udah punya topik yang matang dan siap dijadiin proposal."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-022', '122', 22, 'Gipsy Research', 'Fase 2 — Penelusuran Literatur dan Referensi', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Literatur yang kuat itu yang banyak, relevan, dan up-to-date."}, {"scene": "Body — kalimat 1", "script": "Fase 2 100 Langkah Gipsy Research ngajarin kamu cara nyusun strategi pencarian jurnal."}, {"scene": "Body — kalimat 2", "script": "Mulai dari teknik keyword, sumber database yang bagus, sampe cara ngevaluasi kualitas artikel."}, {"scene": "Body — kalimat 3", "script": "Kamu juga dapet akses ke Pencari Artikel Ilmiah PRO — 250 juta+ artikel terindeks."}, {"scene": "Body — kalimat 4", "script": "Tiap artikel bisa langsung kamu rangkum tanpa harus baca full-text dulu."}, {"scene": "Body — kalimat 5", "script": "Setelah fase ini selesai, kamu punya kumpulan literatur yang siap jadi pondasi bab 1."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-023', '123', 23, 'Gipsy Research', 'Fase 3 — Konstruksi Masalah dan Pendahuluan', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Bab 1 yang kuat bukan karena panjangnya — tapi karena nyambung dari awal sampai akhir."}, {"scene": "Body — kalimat 1", "script": "Fase 3 100 Langkah Gipsy Research khusus ngebantu kamu nyusun Konstruksi Masalah dan Pendahuluan."}, {"scene": "Body — kalimat 2", "script": "Kamu diajarin cara nyusun latar belakang, identifikasi masalah, sampe tujuan penelitian yang logis."}, {"scene": "Body — kalimat 3", "script": "Ada template yang bisa langsung kamu pake dan adaptasi sesuai topik kamu."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngecek alur logika antar-paragraf kamu udah nyambung apa belum."}, {"scene": "Body — kalimat 5", "script": "Setelah fase ini selesai, bab 1 kamu punya fondasi yang kuat buat nyambung ke bab-bab selanjutnya."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-024', '124', 24, 'Gipsy Research', 'Fase 4 — Landasan Teori dan Hipotesis', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Teori dan hipotesis itu bukan formalitas — itu kompas riset kamu."}, {"scene": "Body — kalimat 1", "script": "Fase 4 100 Langkah Gipsy Research ngajarin kamu cara nyusun Landasan Teori yang relevan."}, {"scene": "Body — kalimat 2", "script": "Mulai dari milih teori yang sesuai topik, sampe cara nyusun variabel dan definisi operasionalnya."}, {"scene": "Body — kalimat 3", "script": "Kamu juga diajarin cara ngebangun hipotesis yang bisa diuji — bukan asal nulis."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngebantu kamu ngecek konsistensi teori, variabel, dan hipotesis kamu."}, {"scene": "Body — kalimat 5", "script": "Setelah fase ini selesai, kamu punya kerangka berpikir yang jelas dan bisa dipertanggungjawabkan."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-025', '125', 25, 'Gipsy Research', 'Fase 5 — Desain Metodologi Penelitian', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Metode yang dipilih bukan karena tren — tapi karena cocok sama riset kamu."}, {"scene": "Body — kalimat 1", "script": "Fase 5 100 Langkah Gipsy Research ngajarin kamu cara nentuin Desain Metodologi Penelitian."}, {"scene": "Body — kalimat 2", "script": "Mulai dari pendekatan kualitatif, kuantitatif, atau mixed method — semuanya dijelasin kapan pake yang mana."}, {"scene": "Body — kalimat 3", "script": "Kamu dapet worksheet yang ngebantu kamu nentuin pilihan berdasarkan topik dan pertanyaan riset kamu."}, {"scene": "Body — kalimat 4", "script": "Plus video materi yang nunjukin contoh desain metodologi dari riset yang udah jadi."}, {"scene": "Body — kalimat 5", "script": "Setelah fase ini selesai, bab 3 kamu punya desain yang logis dan bisa diterima dosen."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
