  ('lib-gipsy-research-100langkah-051', '151', 51, 'Gipsy Research', 'Proposal Ditolak? Tahu Bagian Mana yang Harus Direvisi', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Proposal ditolak itu bukan akhir. Tapi biasanya bikin kita bingung harus revisi dari mana."}, {"scene": "Body — kalimat 1", "script": "Banyak yang abis ditolak malah stuck lebih lama, karena nggak tau bagian mana yang harus dibenerin."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research punya Fase 3 yang khusus ngebantu kamu nyusun Konstruksi Masalah yang solid."}, {"scene": "Body — kalimat 3", "script": "Mulai dari latar belakang, rumusan masalah, sampe tujuan — semua dijelasin gimana nyusun yang logis."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngecek konsistensi antar-bagian proposal kamu."}, {"scene": "Body — kalimat 5", "script": "Jadi setelah revisi, proposal kamu bukan cuma “diperbaiki” — tapi beneran lebih kuat."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-052', '152', 52, 'Gipsy Research', 'Revisi Bab 1 Berulang? Fondasi yang Belum Kokoh', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Revisi bab 1 puluhan kali? Itu tandanya bukan kamu nggak bisa — tapi fondasinya belum kokoh."}, {"scene": "Body — kalimat 1", "script": "Biasanya yang direvisi terus bukan nulisnya, tapi logikanya yang kurang nyambung."}, {"scene": "Body — kalimat 2", "script": "Di Fase 3 100 Langkah Gipsy Research, kamu diajarin cara nyusun bab 1 yang nyambung dari paragraf ke paragraf."}, {"scene": "Body — kalimat 3", "script": "Plus worksheet yang ngecek alur logika antar-paragraf kamu."}, {"scene": "Body — kalimat 4", "script": "AI-nya juga bisa ngebantu evaluasi konsistensi bab 1 kamu."}, {"scene": "Body — kalimat 5", "script": "Jadi revisi berikutnya nggak cuma dari dosen — kamu udah bisa evaluasi sendiri dulu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-053', '153', 53, 'Gipsy Research', 'BAB 5 Kesimpulan yang Nggak Asal Tutup', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "BAB 5 itu sering dianggap tinggal kumpulin kalimat. Padahal bisa jadi bagian yang menentukan."}, {"scene": "Body — kalimat 1", "script": "Kesimpulan yang asal biasanya nggak nyambung sama rumusan masalah."}, {"scene": "Body — kalimat 2", "script": "Di Fase 9 100 Langkah Gipsy Research, ada panduan nyusun Kesimpulan & Saran yang nyambung ke pembahasan."}, {"scene": "Body — kalimat 3", "script": "Kamu dapet template yang bisa langsung adaptasi sesuai hasil riset kamu."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngecek apakah kesimpulan kamu beneran jawab semua rumusan masalah."}, {"scene": "Body — kalimat 5", "script": "Jadi BAB 5 kamu nggak cuma nge-close bab — tapi juga ninggalin kesan akhir yang kuat."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-054', '154', 54, 'Gipsy Research', 'Surveynya Sepi? Teknik Distribusi yang Lebih Tepat', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Surveynya sepi itu masalah klasik. Tapi biasanya bukan karena orangnya males."}, {"scene": "Body — kalimat 1", "script": "Tapi karena teknik distribusi dan desain kuesionernya yang kurang tepat."}, {"scene": "Body — kalimat 2", "script": "Di Fase 7 100 Langkah Gipsy Research, ada panduan distribusi kuesioner yang efektif."}, {"scene": "Body — kalimat 3", "script": "Mulai dari teknik pemilihan responden, cara atur kuesioner biar cepet diisi, sampe teknik follow-up."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngebantu kamu ngitung target responden yang realistis."}, {"scene": "Body — kalimat 5", "script": "Jadi data yang masuk bisa cukup — bukan karena paksa orang, tapi karena cara distribusi yang pas."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-055', '155', 55, 'Gipsy Research', 'Teknik Sampling yang Tepat Sesuai Metode', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Sampling itu bagian yang sering bikin mahasiswa bingung. Tekniknya banyak, beda-beda lagi."}, {"scene": "Body — kalimat 1", "script": "Salah pilih teknik sampling bisa bikin hasil penelitian kamu nggak valid."}, {"scene": "Body — kalimat 2", "script": "Di Fase 7 100 Langkah Gipsy Research, ada panduan teknik sampling yang relevan."}, {"scene": "Body — kalimat 3", "script": "Mulai dari probability sampling, non-probability, sampe purposive — semuanya dijelasin kapan pake yang mana."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngebantu kamu nentuin teknik yang pas sama metode kamu."}, {"scene": "Body — kalimat 5", "script": "Jadi teknik sampling kamu bukan asal pilih — tapi beneran disesuaikan sama desain riset kamu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-056', '156', 56, 'Gipsy Research', 'Olah Data Manual di SPSS atau Excel? Ada Cara yang Lebih Efisien', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Olah data manual di SPSS atau Excel tuh makan waktu. Belum lagi kalau formula-nya lupa."}, {"scene": "Body — kalimat 1", "script": "Banyak mahasiswa stuck berjam-jam cuma buat satu analisis."}, {"scene": "Body — kalimat 2", "script": "Di Fase 8 100 Langkah Gipsy Research, ada 15 langkah khusus Olah Data yang ngarahin kamu step by step."}, {"scene": "Body — kalimat 3", "script": "Tiap analisis dijelasin prosesnya, plus tools AI yang bisa bantuin langkah teknisnya."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu nggak perlu hafalin rumus atau syntax yang ribet."}, {"scene": "Body — kalimat 5", "script": "Yang penting kamu paham logikanya — selebihnya tinggal dieksekusi."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-057', '157', 57, 'Gipsy Research', 'Wawancara Tidak Karuan? Pedoman yang Lebih Terstruktur', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Wawancara tuh bagian yang tricky. Apalagi kalau respondennya ngeawang-ngawang."}, {"scene": "Body — kalimat 1", "script": "Hasil wawancara yang nggak fokus biasanya bikin analisis kamu susah."}, {"scene": "Body — kalimat 2", "script": "Di Fase 6 100 Langkah Gipsy Research, ada panduan nyusun pedoman wawancara yang terstruktur."}, {"scene": "Body — kalimat 3", "script": "Plus tips teknik probing biar dapet jawaban yang lebih dalam."}, {"scene": "Body — kalimat 4", "script": "AI-nya juga bisa bantu kamu nyusun draft pedoman wawancara dari variabel kamu."}, {"scene": "Body — kalimat 5", "script": "Jadi wawancara kamu nggak cuma ngeumpul data — tapi dapet data yang beneran bisa dianalisis."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-058', '158', 58, 'Gipsy Research', 'Literatur Bahasa Inggris? Akses Artikel + Rangkuman Otomatis', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Cari literatur bahasa Inggris itu tantangan sendiri. Apalagi kalau bahasa Inggris kamu belum fasih."}, {"scene": "Body — kalimat 1", "script": "Banyak mahasiswa stuck baca jurnal English karena vocab teknisnya banyak."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, Pencari Artikel Ilmiah PRO nyediain rangkuman singkat tiap artikel."}, {"scene": "Body — kalimat 3", "script": "Jadi kamu bisa tau isinya relevan apa nggak, tanpa harus baca full-text dulu."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngebantu kamu nyusun strategi pencarian pakai keyword yang tepat."}, {"scene": "Body — kalimat 5", "script": "Hasilnya, referensi bahasa Inggris kamu lebih banyak — tanpa harus struggle bahasa."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-059', '159', 59, 'Gipsy Research', 'Format Sitasi APA / MLA / Chicago yang Nggak Bikin Pusing', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Sitasi itu detail kecil yang suka bikin pusing. APA, MLA, Chicago — beda-beda lagi."}, {"scene": "Body — kalimat 1", "script": "Salah format sitasi biasanya bikin dosen langsung revisi tanpa mikir panjang."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, ada panduan sitasi yang ngertiin perbedaan format umum."}, {"scene": "Body — kalimat 3", "script": "Plus worksheet yang ngecek konsistensi sitasi kamu dari awal sampai akhir."}, {"scene": "Body — kalimat 4", "script": "AI-nya juga bisa bantu kamu generate daftar pustaka otomatis sesuai format yang kamu pilih."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu nggak perlu hafalin tiap detail — semuanya tinggal konsisten."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-060', '160', 60, 'Gipsy Research', 'Visualisasi Data yang Tepat di BAB 4', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "BAB 4 yang penuh tabel tuh sering bukan karena datanya banyak — tapi karena nggak tau cara visualisasi yang tepat."}, {"scene": "Body — kalimat 1", "script": "Tabel yang asal numpuk biasanya malah bikin pembaca bingung."}, {"scene": "Body — kalimat 2", "script": "Di Fase 8 100 Langkah Gipsy Research, ada panduan milih antara tabel, grafik, atau chart."}, {"scene": "Body — kalimat 3", "script": "Tiap visualisasi dijelasin kapan pake yang mana sesuai jenis datanya."}, {"scene": "Body — kalimat 4", "script": "Plus tools AI yang ngebantu kamu bikin visualisasi yang sesuai standar akademik."}, {"scene": "Body — kalimat 5", "script": "Jadi BAB 4 kamu bukan cuma data — tapi visualisasi yang ngekuatin narasi kamu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-061', '161', 61, 'Gipsy Research', 'Takut Plagiarisme? Parafrase yang Benar dan Tetap Orisinil', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Takut plagiarisme itu wajar. Tapi kebanyakan mahasiswa bingung ngehindarinya gimana."}, {"scene": "Body — kalimat 1", "script": "Banyak yang parnoid, akhirnya jadi nggak ngutip sama sekali."}, {"scene": "Body — kalimat 2", "script": "Di Fase 2 100 Langkah Gipsy Research, ada panduan cara parafrase yang baik dan benar."}, {"scene": "Body — kalimat 3", "script": "Plus tips cara sitasi yang konsisten biar semuanya tetep credited ke sumber asli."}, {"scene": "Body — kalimat 4", "script": "AI-nya bisa bantu kamu parafrase sambil tetep jaga orisinalitas argumen."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu tetep aman secara akademik — tanpa harus kehilangan orisinalitas."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-062', '162', 62, 'Gipsy Research', 'Sidang Mepet? Prioritas yang Jelas di Fase 10', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Sidang tinggal 2 minggu, bab 4 belum kelar? Situasi yang sering bikin panik."}, {"scene": "Body — kalimat 1", "script": "Tapi mepet bukan berarti nggak bisa dilakuin. Asal tau urutan yang paling kritikal."}, {"scene": "Body — kalimat 2", "script": "Fase 10 100 Langkah Gipsy Research punya 5 langkah khusus Persiapan Sidang."}, {"scene": "Body — kalimat 3", "script": "Mulai dari checklist dokumen, sampe template materi presentasi."}, {"scene": "Body — kalimat 4", "script": "Plus ada tips cara bagi waktu biar bagian yang paling penting bisa kelar dulu."}, {"scene": "Body — kalimat 5", "script": "Jadi meskipun mepet, kamu tetep bisa ngejalaninnya dengan lebih terarah."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-063', '163', 63, 'Gipsy Research', 'Mau Ganti Judul? Evaluasi Dulu, Jangan Karena Panik', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Sesekali muncul pikiran buat ganti judul. Itu bukan hal yang aneh — tapi biasanya karena stuck di fase yang salah."}, {"scene": "Body — kalimat 1", "script": "Ganti judul bukan solusi utama kalau fondasi di fase awal belum mateng."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research bantu kamu evaluasi dulu — emang masalahnya di judul atau di pendekatannya."}, {"scene": "Body — kalimat 3", "script": "Fase 1 ngajarin kamu brainstorm ulang tanpa harus ganti judul total."}, {"scene": "Body — kalimat 4", "script": "Kalau emang harus ganti, AI-nya bisa bantu kamu eksplor topik baru dengan cepat."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu nggak ganti judul karena panik — tapi karena emang udah ada alternatif yang lebih kuat."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-064', '164', 64, 'Gipsy Research', 'Bosan di Tengah Jalan? Sistem yang Ngurangin Overwhelm', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Week 3, week 5, week 8 — biasanya mulai ada titik bosan di skripsi."}, {"scene": "Body — kalimat 1", "script": "Itu manusiawi. Tapi kalau dibiarin, biasanya skripsi molor berbulan-bulan."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, ada 10 fase yang dipecah jadi langkah-langkah kecil."}, {"scene": "Body — kalimat 3", "script": "Jadi kamu nggak ngerjain proyek raksasa — tapi langkah-langkah kecil yang bisa dikerjain rutin."}, {"scene": "Body — kalimat 4", "script": "Plus quiz dan worksheet yang ngasih feedback instan biar kamu tau progresmu."}, {"scene": "Body — kalimat 5", "script": "Hasilnya, kamu tetep konsisten meskipun lagi nggak mood."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-065', '165', 65, 'Gipsy Research', 'Motivasi Naik Turun? Sistem yang Konsisten', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Motivasi itu bisa naik turun. Tapi kalau terlalu sering turun, biasanya ada masalah di sistemnya."}, {"scene": "Body — kalimat 1", "script": "Ngerjain proyek besar tanpa breakdown = motivasi cepet habis."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research mecah skripsi jadi 10 fase × beberapa langkah kecil."}, {"scene": "Body — kalimat 3", "script": "Tiap langkah punya output yang jelas, jadi tiap hari kamu bisa liat progres."}, {"scene": "Body — kalimat 4", "script": "Plus ada Review Draft dari mentor yang bisa kasih semangat lewat feedback."}, {"scene": "Body — kalimat 5", "script": "Jadi motivasimu naik karena sistemnya jalan — bukan karena dipaksa sendiri."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-066', '166', 66, 'Gipsy Research', 'Mulai dari Proposal atau Bab 1? Urutan yang Tepat', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Banyak yang bingung, pertama ngerjain proposal dulu atau langsung bab 1."}, {"scene": "Body — kalimat 1", "script": "Salah urutan biasanya bikin kamu revisi dua kali."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research punya Fase 3 yang ngertiin urutan yang tepat: mulai dari Konstruksi Masalah."}, {"scene": "Body — kalimat 3", "script": "Itu nanti jadi dasar bab 1 kamu — bukan kerja dua kali."}, {"scene": "Body — kalimat 4", "script": "Plus Fase 1 dan 2 ngebantu kamu siapin topik dan literatur dulu sebelum masuk ke sana."}, {"scene": "Body — kalimat 5", "script": "Jadi urutannya jelas dari awal — nggak ada lagi kerja dobel."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-067', '167', 67, 'Gipsy Research', 'Outline Skripsi yang Konsisten Antar-Bab', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Outline skripsi yang nggak nyambung antar-bab tuh masalah yang baru keliatan di tengah."}, {"scene": "Body — kalimat 1", "script": "Bab 1 ngomongin A, bab 4 malah ke B — biasanya revisi jadi banyak."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, tiap fase ngertiin gimana output-nya nyambung ke fase selanjutnya."}, {"scene": "Body — kalimat 3", "script": "Mulai dari outline bab 1, outline bab 2, sampe outline bab 4 — semua dijelasin nyambungnya gimana."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngecek konsistensi antar-bab."}, {"scene": "Body — kalimat 5", "script": "Jadi outline kamu bukan cuma ada — tapi nyambung dan logis."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-068', '168', 68, 'Gipsy Research', 'Topik Terlalu Luas? Cara Nyempitkan Tanpa Kehilangan Esensi', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Topik yang terlalu luas itu klasik. Tapi biasanya bukan karena idenya jelek."}, {"scene": "Body — kalimat 1", "script": "Tapi karena belum di-scope down sesuai kemampuan dan waktu yang tersedia."}, {"scene": "Body — kalimat 2", "script": "Di Fase 1 100 Langkah Gipsy Research, ada panduan nyempitkan topik tanpa kehilangan esensinya."}, {"scene": "Body — kalimat 3", "script": "Worksheet-nya ngebantu kamu tentuin batasan penelitian yang realistis."}, {"scene": "Body — kalimat 4", "script": "Plus AI yang bantu kamu evaluasi kelayakan topik dari berbagai aspek."}, {"scene": "Body — kalimat 5", "script": "Hasilnya, topik kamu tetep menarik — tapi lebih manageable buat dijadiin skripsi."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-069', '169', 69, 'Gipsy Research', '20+ Materi dan Template yang Disesuaikan per Fase', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Materi itu banyak. Tapi yang kamu butuhin bukan semuanya — yang relevan sama fase kamu."}, {"scene": "Body — kalimat 1", "script": "Di 100 Langkah Gipsy Research, ada 20+ materi & template yang disesuaikan per fase."}, {"scene": "Body — kalimat 2", "script": "Mulai dari template bab 1–5, checklist sidang, sampe template kuesioner."}, {"scene": "Body — kalimat 3", "script": "Tiap materi udah disesuaikan sama output yang dibutuhin di fase tersebut."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu nggak perlu nyari sendiri di tempat lain — semuanya ada di sini."}, {"scene": "Body — kalimat 5", "script": "Tinggal buka fase yang lagi kamu jalanin, langsung tau materi mana yang dibutuhin."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-070', '170', 70, 'Gipsy Research', 'Template Bab 1 yang Siap Adaptasi', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Bab 1 tuh pondasi. Tapi nulisnya dari nol tuh makan waktu."}, {"scene": "Body — kalimat 1", "script": "Di 100 Langkah Gipsy Research, ada template Bab 1 yang udah disesuaikan standar akademik."}, {"scene": "Body — kalimat 2", "script": "Mulai dari latar belakang, rumusan masalah, tujuan, sampe manfaat penelitian."}, {"scene": "Body — kalimat 3", "script": "Tiap bagian udah ada strukturnya — tinggal kamu isi sesuai topik."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngecek apakah tiap bagian udah cukup kuat."}, {"scene": "Body — kalimat 5", "script": "Jadi bab 1 kamu lebih ringkes disusun — tanpa kehilangan kualitasnya."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-071', '171', 71, 'Gipsy Research', 'Template Bab 2 yang Ngarahin Landasan Teori', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Bab 2 itu landasan teori. Banyak yang stuck di sini karena referensi terlalu banyak."}, {"scene": "Body — kalimat 1", "script": "Tapi landasan teori yang baik bukan yang semuanya dibahas — yang relevan aja."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, ada template Bab 2 yang ngarahin cara milih teori yang relevan."}, {"scene": "Body — kalimat 3", "script": "Plus cara nyusun alur antar-sub-bab biar nyambung."}, {"scene": "Body — kalimat 4", "script": "Worksheet-nya ngebantu kamu ngecek konsistensi rujukan kamu di setiap paragraf."}, {"scene": "Body — kalimat 5", "script": "Jadi bab 2 kamu bukan cuma kumpulan teori — tapi yang beneran nyambung ke riset kamu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-072', '172', 72, 'Gipsy Research', 'Template Bab 3 yang Metodologis', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Bab 3 itu metodologi. Salah nulis di sini biasanya bikin sidang langsung revisi."}, {"scene": "Body — kalimat 1", "script": "Di 100 Langkah Gipsy Research, ada template Bab 3 yang ngertiin detail tiap bagian metodologi."}, {"scene": "Body — kalimat 2", "script": "Mulai dari pendekatan penelitian, populasi, sampel, teknik sampling, sampe teknik analisis."}, {"scene": "Body — kalimat 3", "script": "Tiap bagian dijelasin gimana nulisnya yang jelas dan bisa direplikasi."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngecek apakah desain kamu beneran bisa dijalanin."}, {"scene": "Body — kalimat 5", "script": "Jadi bab 3 kamu kelihatan metodologis, bukan cuma copy-paste template."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-073', '173', 73, 'Gipsy Research', 'Template Bab 4 yang Argumentatif', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Bab 4 itu inti analisis. Tapi banyak yang bingung gimana mulai dari data mentah."}, {"scene": "Body — kalimat 1", "script": "Di 100 Langkah Gipsy Research, ada template Bab 4 yang ngarahin kamu dari analisis sampe pembahasan."}, {"scene": "Body — kalimat 2", "script": "Mulai dari deskripsi data, analisis hasil, sampe argumentasi yang nyambung."}, {"scene": "Body — kalimat 3", "script": "Tiap bagian ada contoh dan strukturnya yang bisa langsung kamu adaptasi."}, {"scene": "Body — kalimat 4", "script": "Plus worksheet yang ngebantu kamu nyusun alur logika antar-paragraf."}, {"scene": "Body — kalimat 5", "script": "Jadi bab 4 kamu kelihatan rapi, terstruktur, dan argumentatif."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-074', '174', 74, 'Gipsy Research', 'Template Bab 5 yang Berkarakter', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Bab 5 itu penutup. Banyak yang asal nulis karena udah capek."}, {"scene": "Body — kalimat 1", "script": "Padahal bab 5 yang kuat bisa ninggalin kesan akhir yang positif buat dosen."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, ada template Bab 5 yang ngarahin kamu nyusun kesimpulan yang nyambung."}, {"scene": "Body — kalimat 3", "script": "Plus cara nyusun saran yang relevan dan realistis."}, {"scene": "Body — kalimat 4", "script": "Worksheet-nya ngecek apakah kesimpulan kamu beneran jawab semua rumusan masalah."}, {"scene": "Body — kalimat 5", "script": "Jadi bab 5 kamu tetep berkarakter, bukan cuma paragraf penutup yang datar."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-075', '175', 75, 'Gipsy Research', 'Checklist Sidang — Kelengkapan Dokumen Lengkap', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Jelang sidang, biasanya yang bikin panik bukan materinya — tapi kelengkapan administrasi."}, {"scene": "Body — kalimat 1", "script": "Hard cover, lembar pengesahan, daftar hadir — semua harus lengkap."}, {"scene": "Body — kalimat 2", "script": "Di Fase 10 100 Langkah Gipsy Research, ada checklist lengkap dokumen sidang."}, {"scene": "Body — kalimat 3", "script": "Mulai dari dokumen hardcopy sampe softcopy, plus dokumen pendukung lainnya."}, {"scene": "Body — kalimat 4", "script": "Kamu tinggal checklist satu per satu — biar nggak ada yang kelewat."}, {"scene": "Body — kalimat 5", "script": "Jadi pas hari H, kamu fokus presentasi — bukan panik nyari dokumen yang kurang."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-076', '176', 76, 'Gipsy Research', 'AI untuk Brainstorm Topik di Fase 1', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Brainstorm topik itu bagian yang sering berlarut-larut. Apalagi kalau belum ada bayangan sama sekali."}, {"scene": "Body — kalimat 1", "script": "Di Fase 1 100 Langkah Gipsy Research, ada tools AI khusus buat brainstorm."}, {"scene": "Body — kalimat 2", "script": "Tinggal masukin kata kunci, dan AI-nya ngasih variasi topik yang bisa kamu eksplor."}, {"scene": "Body — kalimat 3", "script": "Plus ada worksheet yang ngebantu kamu evaluasi kelayakan tiap topik."}, {"scene": "Body — kalimat 4", "script": "Jadi brainstorming kamu lebih terarah — tanpa kehilangan kualitas eksplorasinya."}, {"scene": "Body — kalimat 5", "script": "Tiap topik yang muncul udah difilter sama AI biar sesuai sama bidang studi kamu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-077', '177', 77, 'Gipsy Research', 'AI untuk Cari Jurnal dengan Strategi Keyword', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Cari jurnal itu makan waktu. Apalagi kalau keyword-nya masih umum."}, {"scene": "Body — kalimat 1", "script": "Di 100 Langkah Gipsy Research, Pencari Artikel Ilmiah PRO udah terpasang sama AI-nya."}, {"scene": "Body — kalimat 2", "script": "AI-nya bantu nyusun strategi pencarian yang lebih spesifik dari keyword kamu."}, {"scene": "Body — kalimat 3", "script": "Tiap artikel yang relevan langsung muncul dengan rangkuman singkat."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu bisa langsung filter — tanpa harus buka satu-satu."}, {"scene": "Body — kalimat 5", "script": "Lebih efisien baca literatur, kualitas tetep terjaga."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-078', '178', 78, 'Gipsy Research', 'AI untuk Menyusun Draft Bab 1', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Nulis bab 1 tuh sering jadi beban tersendiri. Background, rumusan masalah, tujuan — semuanya harus nyambung."}, {"scene": "Body — kalimat 1", "script": "Di Fase 3 100 Langkah Gipsy Research, ada AI yang ngebantu nyusun draft bab 1."}, {"scene": "Body — kalimat 2", "script": "AI-nya bisa bantuin outline, draf paragraf awal, atau evaluasi konsistensi logika."}, {"scene": "Body — kalimat 3", "script": "Plus worksheet yang ngecek apakah tiap paragraf nyambung ke alur bab 1."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu bisa lebih fokus ke arah dan substansi — bukan teknis nulis."}, {"scene": "Body — kalimat 5", "script": "Hasilnya, bab 1 kamu lebih ringkes disusun — dengan kualitas yang tetep terjaga."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-079', '179', 79, 'Gipsy Research', 'AI untuk Olah Data di Fase 8', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Olah data tuh sering bikin stuck. Excel error, SPSS bingung — itu klasik."}, {"scene": "Body — kalimat 1", "script": "Di Fase 8 100 Langkah Gipsy Research, ada AI yang ngebantuin olah data."}, {"scene": "Body — kalimat 2", "script": "AI-nya bisa bantuin cleaning data, analisis deskriptif, sampe uji hipotesis."}, {"scene": "Body — kalimat 3", "script": "Kamu diajarin logikanya step by step, bukan cuma output akhirnya."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu paham analisisnya, bukan cuma dapet hasilnya."}, {"scene": "Body — kalimat 5", "script": "Plus hasil analisismu bisa langsung masuk ke BAB 4 kamu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-080', '180', 80, 'Gipsy Research', 'AI untuk Visualisasi Data', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Visualisasi data itu bagian yang sering bikin lama. Apalagi kalau harus bikin chart dari nol."}, {"scene": "Body — kalimat 1", "script": "Di Fase 8 100 Langkah Gipsy Research, ada AI yang bisa bantuin bikin visualisasi."}, {"scene": "Body — kalimat 2", "script": "Tinggal masukin data, AI-nya ngasih rekomendasi chart yang paling pas."}, {"scene": "Body — kalimat 3", "script": "Bar chart, line chart, heatmap, pie chart — semuanya disesuaikan sama jenis datamu."}, {"scene": "Body — kalimat 4", "script": "Hasil visualisasinya bisa langsung kamu pake di bab 4 kamu."}, {"scene": "Body — kalimat 5", "script": "Jadi visualisasimu lebih rapi dan sesuai standar akademik."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-081', '181', 81, 'Gipsy Research', 'AI untuk Cek Grammar dan Gaya Tulis Akademik', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Grammar yang berantakan biasanya langsung keliatan di mata dosen."}, {"scene": "Body — kalimat 1", "script": "Apalagi kalau kamu nulis cepat — typo dan struktur kalimat suka ke skip."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, ada AI yang bisa bantu cek grammar dan gaya nulis akademik."}, {"scene": "Body — kalimat 3", "script": "Bukan buat ganti tulisannya — tapi buat kasih tau bagian mana yang perlu diperbaiki."}, {"scene": "Body — kalimat 4", "script": "Jadi draft kamu tetep asli karyamu — tapi lebih rapi dan profesional."}, {"scene": "Body — kalimat 5", "script": "Cocok buat finalisasi sebelum submit ke dosen atau sidang."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
