  ('lib-gipsy-research-100langkah-087', '187', 87, 'Gipsy Research', '50+ Video Materi yang Ringkas dan Langsung ke Contoh', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Video materi yang bagus itu yang ringkas, jelas, dan langsung ke contoh."}, {"scene": "Body — kalimat 1", "script": "Di 100 Langkah Gipsy Research, ada 50+ video materi yang ngertiin konsep step by step."}, {"scene": "Body — kalimat 2", "script": "Tiap video udah disesuaikan sama fase dan topik yang relevan."}, {"scene": "Body — kalimat 3", "script": "Mulai dari video teori dasar, video cara pake tools, sampe video contoh skripsi."}, {"scene": "Body — kalimat 4", "script": "Durasi video dijaga ringkas — biar kamu bisa belajar kapan aja di sela-sela kegiatan."}, {"scene": "Body — kalimat 5", "script": "Jadi belajarmu nggak cuma teori, tapi juga contoh konkret yang bisa langsung dipake."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-088', '188', 88, 'Gipsy Research', 'Review Draft Pro oleh Mentor Berpengalaman', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Review draft itu bukan cuma soal typo. Tapi soal logika, substansi, sampe cara nulis."}, {"scene": "Body — kalimat 1", "script": "Di 100 Langkah Gipsy Research, fitur Review Draft Penelitian dikerjain mentor berpengalaman."}, {"scene": "Body — kalimat 2", "script": "Mentor-nya nggak cuma ngecek grammar — tapi juga alur logika dan kekuatannya."}, {"scene": "Body — kalimat 3", "script": "Feedback-nya spesifik, jadi kamu tau bagian mana yang perlu dibenerin dan gimana."}, {"scene": "Body — kalimat 4", "script": "Plus, tetep kamu yang nulis — mentor-nya cuma kasih perspektif."}, {"scene": "Body — kalimat 5", "script": "Jadi draft kamu tetep orisinil karya kamu, tapi lebih berkualitas."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-089', '189', 89, 'Gipsy Research', 'Komitmen Proses, Bukan Hasil Instan', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Skripsi itu hasilnya nggak instan — tapi prosesnya bisa kamu kontrol."}, {"scene": "Body — kalimat 1", "script": "Yang nentuin hasilnya bukan apakah kamu pinter, tapi apakah kamu konsisten."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research ngubah skripsi dari “tekanan” jadi “rutinitas kecil yang bisa dikontrol”."}, {"scene": "Body — kalimat 3", "script": "Tiap hari kamu cukup fokus di satu atau dua langkah."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu nggak butuh motivasi super buat mulai — cukup sistem yang jalan."}, {"scene": "Body — kalimat 5", "script": "Hasilnya? Kamu tau persis lagi di mana, dan selanjutnya mau kemana."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
