  ('lib-gipsy-research-100langkah-095', '195', 95, 'Gipsy Research', 'Cerita dari Mereka yang Udah Lewati Prosesnya', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Ada banyak cerita dari mahasiswa yang akhirnya bisa ngejalanin skripsinya dari awal sampe akhir."}, {"scene": "Body — kalimat 1", "script": "Bukan karena cepet pinter — tapi karena akhirnya dapet sistem yang jalan."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, sistemnya yang konsisten bikin ritme kerja mereka kebawa."}, {"scene": "Body — kalimat 3", "script": "Tiap langkah kecil yang dikerjain rutin akhirnya numpuk jadi skripsi yang kelar."}, {"scene": "Body — kalimat 4", "script": "Plus Review Mentor bikin mereka yakin sama kualitas draft mereka."}, {"scene": "Body — kalimat 5", "script": "Itu yang sering kita denger — bukan “keajaiban”, tapi “akhirnya ada jalan”."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-096', '196', 96, 'Gipsy Research', 'Sistem Lengkap, Bukan Sekadar Sesi Bimbingan', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Jasa bimbingan skripsi itu ada banyak — beda-beda lagi kualitasnya."}, {"scene": "Body — kalimat 1", "script": "Tapi kebanyakan cuma ngasih materi atau review — tanpa sistem yang ngarahin kamu."}, {"scene": "Body — kalimat 2", "script": "100 Langkah Gipsy Research bukan program lepas — tapi sistem terstruktur yang ngecover seluruh fase."}, {"scene": "Body — kalimat 3", "script": "Mulai dari nemuin topik, nyusun bab 1, olah data, sampe siap sidang."}, {"scene": "Body — kalimat 4", "script": "Tiap fase ada panduan, worksheet, video, AI tools, dan quiz — plus review mentor."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu nggak cuma dapet “sesi bimbingan” — tapi sistem yang jalan terus selama kamu ngerjain."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-097', '197', 97, 'Gipsy Research', 'Komitmen Belajar yang Realistis', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Komitmen belajar itu penting — tapi komitmen yang berlebihan biasanya nggak bertahan."}, {"scene": "Body — kalimat 1", "script": "Yang keliatan “rajin” 16 jam sehari biasanya cuma bertahan 2 minggu, terus burned out."}, {"scene": "Body — kalimat 2", "script": "Di 100 Langkah Gipsy Research, sistemnya ngajarin kamu kerja konsisten yang ringan."}, {"scene": "Body — kalimat 3", "script": "Tiap hari cukup fokus ke satu atau dua langkah, bukan maraton panjang."}, {"scene": "Body — kalimat 4", "script": "Plus tools AI yang ngebantuin bagian yang makan waktu, biar kamu bisa fokus ke substansi."}, {"scene": "Body — kalimat 5", "script": "Hasilnya, ritme belajar kamu tetep terjaga — tanpa harus keliatan “rajin” palsu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-098', '198', 98, 'Gipsy Research', 'Riset sebagai Skill Jangka Panjang', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Riset itu bukan cuma buat skripsi. Tapi skill yang kepake jangka panjang."}, {"scene": "Body — kalimat 1", "script": "Yang diajarin di 100 Langkah Gipsy Research bukan cuma cara lulus — tapi cara mikir secara ilmiah."}, {"scene": "Body — kalimat 2", "script": "Mulai dari cara nyusun argumen, analisis data, sampe nyusun tulisan yang logis."}, {"scene": "Body — kalimat 3", "script": "Skill ini bakal kepake di dunia kerja, studi lanjut, atau karir akademik."}, {"scene": "Body — kalimat 4", "script": "Plus tools dan metodologinya applicable di konteks lain — bukan cuma skripsi."}, {"scene": "Body — kalimat 5", "script": "Jadi yang kamu dapet bukan cuma skripsi kelar — tapi cara mikir yang bisa kamu bawa ke mana-mana."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-099', '199', 99, 'Gipsy Research', 'Riset sebagai Skill, Bukan Sekadar Kelar', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Riset itu skill. Bukan tugas akhir yang harus kamu selesein terus lupa."}, {"scene": "Body — kalimat 1", "script": "Setelah lulus, skill riset bakal kepake di banyak konteks."}, {"scene": "Body — kalimat 2", "script": "Mulai dari analisis data di kerjaan, sampe cara mikir kritis yang sering dibutuhin profesional."}, {"scene": "Body — kalimat 3", "script": "100 Langkah Gipsy Research ngajarin kamu skill ini — bukan cuma caranya lulus."}, {"scene": "Body — kalimat 4", "script": "Tiap fase ngertiin cara mikir yang logis dan terstruktur — bukan cuma ngerjain soal."}, {"scene": "Body — kalimat 5", "script": "Jadi setelah lulus, kamu punya skill yang relevan — bukan cuma ijazah."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-100', '200', 100, 'Gipsy Research', '100 Langkah sebagai Peta, Bukan sebagai Jawaban', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Itu dia 100 Langkah Gipsy Research — peta yang nuntun kamu dari awal sampai tahap akhir."}, {"scene": "Body — kalimat 1", "script": "Bukan jalan pintas, tapi sistem yang bikin prosesnya jelas."}, {"scene": "Body — kalimat 2", "script": "Kamu yang nulis, kamu yang analisis, kamu yang mempertanggung jawabkan."}, {"scene": "Body — kalimat 3", "script": "AI-nya cuma alat, mentor-nya cuma kasih perspektif."}, {"scene": "Body — kalimat 4", "script": "Hasilnya tetep karya intelektual kamu — yang beneran kamu pahami."}, {"scene": "Body — kalimat 5", "script": "Kalau kamu pengen sistem yang nuntun kamu dari awal sampe akhir, ini bisa jadi awal mulainya."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-101', '201', 101, 'Gipsy Research', 'Skripsi Maraton, Bukan Sprint — GipsyAI + 100 Langkah 1 Tahun', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Skripsi itu maraton, bukan sprint. Tapi sistem kita sering dibuat kayak lomba lari cepat."}, {"scene": "Body — kalimat 1", "script": "Banyak mahasiswa yang abis semester 3-4 langsung dipaksa “cepet kelar” — tanpa ngasih waktu yang realistis."}, {"scene": "Body — kalimat 2", "script": "Padahal riset yang baik butuh waktu — buat eksplorasi, revisi, sampe pematangan."}, {"scene": "Body — kalimat 3", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu dapet waktu 12 bulan buat ngerjain tanpa tekanan “kudu kelar cepet”."}, {"scene": "Body — kalimat 4", "script": "AI-nya nemenin kamu terus, dari awal mikir topik sampe siap sidang."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu bisa ngerjain dengan ritme yang sehat — bukan sprint yang bikin burnout."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-102', '202', 102, 'Gipsy Research', 'Konsistensi 12 Bulan dengan Sistem GipsyAI + 100 Langkah', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Konsistensi itu lebih penting dari sprint. Tapi emang susah sendirian."}, {"scene": "Body — kalimat 1", "script": "Banyak yang semangat 2-3 bulan, terus molor berbulan-bulan, akhirnya kelar tanpa substansi."}, {"scene": "Body — kalimat 2", "script": "Yang bikin konsisten biasanya bukan motivasi — tapi sistem yang jalan setiap hari."}, {"scene": "Body — kalimat 3", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, sistemnya nemenin kamu selama 12 bulan penuh."}, {"scene": "Body — kalimat 4", "script": "Tiap hari kamu bisa akses AI tools, worksheet, video, dan quiz — semuanya terstruktur."}, {"scene": "Body — kalimat 5", "script": "Jadi yang kamu bangun bukan sprint — tapi kebiasaan yang konsisten."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-103', '203', 103, 'Gipsy Research', '12 Bulan untuk Adaptasi Tanpa Tekanan Deadline', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Skripsi yang molor tuh sering disalahin ke “malas”. Padahal bisa karena hal lain."}, {"scene": "Body — kalimat 1", "script": "Topik yang berubah, dosen yang beda standar, sampe data yang susah dikumpulin — semua bisa bikin molor."}, {"scene": "Body — kalimat 2", "script": "Masalahnya, sistem akademik kita jarang ngasih ruang buat situasi kayak gini."}, {"scene": "Body — kalimat 3", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu dapet waktu yang realistis — 12 bulan buat adaptasi."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu nggak buru-buru pas situasi berubah, kamu bisa adjust ritme kamu."}, {"scene": "Body — kalimat 5", "script": "Hasilnya, skripsi kamu tetep jalan — dengan kualitas yang nggak dikorbankan."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-104', '204', 104, 'Gipsy Research', '1 Tahun Eksplorasi Topik yang Lebih Dalam', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Topik yang bagus tuh yang dieksplorasi dalam, bukan yang asal comot."}, {"scene": "Body — kalimat 1", "script": "Tapi eksplorasi yang dalam butuh waktu — yang biasanya nggak dipunyai mahasiswa semester akhir."}, {"scene": "Body — kalimat 2", "script": "Banyak yang akhirnya pilih topik yang terlalu sempit biar cepet, tapi jadi dangkal."}, {"scene": "Body — kalimat 3", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu punya 12 bulan buat eksplorasi yang lebih dalam."}, {"scene": "Body — kalimat 4", "script": "Mulai dari baca literatur lebih banyak, eksplor perspektif, sampe nyusun kerangka yang kuat."}, {"scene": "Body — kalimat 5", "script": "Jadi topik kamu tetep menarik — dengan kedalaman yang sebenernya."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-105', '205', 105, 'Gipsy Research', 'Fleksibilitas Outline dengan 12 Bulan Akses', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Outline skripsi yang berubah di tengah jalan tuh bukan hal aneh."}, {"scene": "Body — kalimat 1", "script": "Especially kalau pas olah data, kamu nemu hal yang nggak sesuai dengan asumsi awal."}, {"scene": "Body — kalimat 2", "script": "Tapi sistem yang kaku biasanya bikin kamu stuck di outline lama — meskipun datanya udah beda."}, {"scene": "Body — kalimat 3", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu punya fleksibilitas buat adjust outline tanpa harus restart."}, {"scene": "Body — kalimat 4", "script": "Tiap fase ngertiin gimana nyusun ulang logika skripsi kalau arah risetnya berubah."}, {"scene": "Body — kalimat 5", "script": "Jadi skripsi kamu tetep nyambung — meskipun ada perubahan arah di tengah jalan."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-106', '206', 106, 'Gipsy Research', '12 Bulan Iterasi untuk BAB 4 yang Lebih Mateng', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "BAB 4 itu bagian yang sering paling lama. Bukan karena males — tapi emang butuh iterasi."}, {"scene": "Body — kalimat 1", "script": "Argumen yang nyambung, visualisasi yang tepat, sampe pembahasan yang logis — semua butuh revisi."}, {"scene": "Body — kalimat 2", "script": "Tapi sistem yang ngasih waktu terbatas bikin mahasiswa ngebut tanpa peduli kualitas."}, {"scene": "Body — kalimat 3", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu punya 12 bulan buat nge-iterasi BAB 4 kamu."}, {"scene": "Body — kalimat 4", "script": "Mulai dari olah data, visualisasi, sampe nyusun argumen yang nyambung."}, {"scene": "Body — kalimat 5", "script": "Jadi BAB 4 kamu bukan cuma kelar — tapi beneran berkualitas."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-107', '207', 107, 'Gipsy Research', '12 Bulan untuk Matengin Skripsi + Persiapan Sidang', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Sidang yang tertunda tuh bukan berarti kamu gagal."}, {"scene": "Body — kalimat 1", "script": "Banyak faktor yang bikin sidang molor — dan itu bukan hal yang aneh."}, {"scene": "Body — kalimat 2", "script": "Yang penting bukan cepet sidangnya, tapi kamu siap pas waktunya."}, {"scene": "Body — kalimat 3", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu punya waktu buat matengin seluruh skripsi kamu."}, {"scene": "Body — kalimat 4", "script": "Termasuk persiapan sidang yang lebih mateng — bukan lompatan tiba-tiba."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu bisa ngejalanin sidang dengan lebih tenang."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-108', '208', 108, 'Gipsy Research', 'Waktu Realistis 1 Tahun untuk Skripsi yang Berkualitas', 'TOFU — Awareness', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Skripsi yang baik itu yang dikembangin dengan waktu yang cukup, bukan yang dikebut."}, {"scene": "Body — kalimat 1", "script": "Tapi sistem akademik kita sering bikin mahasiswa ngebut di akhir semester."}, {"scene": "Body — kalimat 2", "script": "Tanpa ngasih ruang buat pematangan ide, eksplorasi data, atau revisi yang substantif."}, {"scene": "Body — kalimat 3", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu bisa ambil waktu yang kamu butuhin."}, {"scene": "Body — kalimat 4", "script": "12 bulan penuh buat ngerjain tanpa dikejar deadline kampus."}, {"scene": "Body — kalimat 5", "script": "Jadi skripsi kamu bisa tetep berkualitas — meskipun ritmenya lebih santai."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-109', '209', 109, 'Gipsy Research', 'Release Baru: Langganan 1 Tahun GipsyAI + 100 Langkah', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Gipsy Research baru aja release langganan 1 tahun untuk GipsyAI + 100 Langkah. Dan ini bukan cuma soal lebih panjang."}, {"scene": "Body — kalimat 1", "script": "Yang berubah bukan cuma durasinya — tapi cara kamu ngerjain skripsi."}, {"scene": "Body — kalimat 2", "script": "Dengan 12 bulan akses, kamu punya waktu buat nge-eksplorasi, eksperimen, dan revisi tanpa dikejar waktu."}, {"scene": "Body — kalimat 3", "script": "GipsyAI-nya nemenin kamu terus — dari brainstorm topik sampai olah data."}, {"scene": "Body — kalimat 4", "script": "100 Langkah-nya ngatur urutannya, sementara 10+ kelas online, 250jt+ artikel, dan Review Mentor nemenin dari samping."}, {"scene": "Body — kalimat 5", "script": "Jadi ini bukan cuma “langganan lebih panjang” — tapi model baru yang ngedukung proses kamu yang real."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-110', '210', 110, 'Gipsy Research', '12 Bulan Akses Penuh ke GipsyAI dan 100 Langkah', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "12 bulan akses penuh GipsyAI + 100 Langkah. Itu yang baru aja di-release."}, {"scene": "Body — kalimat 1", "script": "Sekarang kamu bisa pake seluruh tools GipsyAI dan seluruh fase 100 Langkah selama setahun penuh."}, {"scene": "Body — kalimat 2", "script": "Dari sisi GipsyAI: 40+ AI apps yang udah di-setting sesuai konteks skripsi."}, {"scene": "Body — kalimat 3", "script": "Dari sisi 100 Langkah: 50+ video materi, 20+ worksheet, 10+ quiz — bisa kamu pake kapan aja selama 12 bulan."}, {"scene": "Body — kalimat 4", "script": "Plus akses ke 250jt+ artikel ilmiah dan Review Draft Penelitian dari mentor."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu dapet “toolkit” lengkap buat setahun ngerjain skripsi."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-111', '211', 111, 'Gipsy Research', 'Fleksibilitas 1 Tahun Tanpa Tekanan Deadline', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Skripsi itu bukan lomba. Tapi sistem kita sering bikin kerasa kayak lomba."}, {"scene": "Body — kalimat 1", "script": "Deadline semester, sidang yang dijadwalkan, dosen yang nungguin — semua bikin tekanan."}, {"scene": "Body — kalimat 2", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu bisa ambil nafas."}, {"scene": "Body — kalimat 3", "script": "12 bulan buat ngerjain dengan ritme yang kamu tentuin sendiri."}, {"scene": "Body — kalimat 4", "script": "Mau cepet? Bisa. Mau santai? Bisa. Yang penting prosesnya jalan."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu tetep konsisten — tanpa tekanan yang bikin burnout."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-112', '212', 112, 'Gipsy Research', 'Pendampingan Konsisten Selama 12 Bulan', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Yang sering bikin skripsi molor bukan materinya — tapi pendampingan yang putus-putus."}, {"scene": "Body — kalimat 1", "script": "Bimbingan dosen yang jarang, diskusi yang sebentar, sampe feedback yang telat."}, {"scene": "Body — kalimat 2", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu dapet pendampingan yang konsisten selama 12 bulan."}, {"scene": "Body — kalimat 3", "script": "Mulai dari Review Draft Penelitian yang bisa kamu request kapan aja."}, {"scene": "Body — kalimat 4", "script": "Plus 10+ kelas online yang bisa kamu ulang-ulang sampe paham."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu nggak jalan sendirian — ada sistem yang nemenin kamu selama setahun."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-113', '213', 113, 'Gipsy Research', '1 Tahun untuk Riset yang Butuh Waktu Panjang', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Riset yang butuh waktu panjang tuh sering nggak diakomodasi sama sistem semester."}, {"scene": "Body — kalimat 1", "script": "Especially untuk topik yang kompleks, butuh data longitudinal, atau analisis yang iteratif."}, {"scene": "Body — kalimat 2", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu punya waktu yang realistis."}, {"scene": "Body — kalimat 3", "script": "12 bulan buat ngumpulin data, eksplorasi pendekatan, sampe nyempurnain analisis."}, {"scene": "Body — kalimat 4", "script": "GipsyAI bantuin di bagian teknis, sementara 100 Langkah ngingetin urutan mestinya."}, {"scene": "Body — kalimat 5", "script": "Jadi kamu nggak maksain riset kamu masuk ke deadline yang terlalu sempit."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-114', '214', 114, 'Gipsy Research', '1 Tahun untuk yang Sambil Kerja', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Ngerjain skripsi sambil kerja tuh butuh waktu yang lebih fleksibel."}, {"scene": "Body — kalimat 1", "script": "Karena energimu terbagi, dan deadline kampus sering nggak match sama ritme kerjamu."}, {"scene": "Body — kalimat 2", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu punya buffer waktu 12 bulan."}, {"scene": "Body — kalimat 3", "script": "Tiap langkah kecil bisa kamu kerjain di sela-sela kerjaan — tanpa harus ngebut marathon."}, {"scene": "Body — kalimat 4", "script": "Plus AI-nya ngebantuin bagian yang makan waktu, biar kamu hemat energi."}, {"scene": "Body — kalimat 5", "script": "Jadi skripsi kamu tetep jalan — meskipun ritme kerjaanmu padet."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-115', '215', 115, 'Gipsy Research', '1 Tahun untuk yang Baru Mulai Skripsi', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Baru mulai skripsi dan bingung dari mana? 1 tahun itu waktu yang cukup."}, {"scene": "Body — kalimat 1", "script": "Mulai dari bangun fondasi, cari literatur, nyusun proposal, sampe siap sidang."}, {"scene": "Body — kalimat 2", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu bisa ngejalanin semuanya tanpa dikejar deadline."}, {"scene": "Body — kalimat 3", "script": "Tiap fase dijelasin step by step, dan AI-nya nemenin kamu di setiap langkah."}, {"scene": "Body — kalimat 4", "script": "Jadi kamu bisa fokus ke belajar prosesnya — tanpa panik “cepet kelar”."}, {"scene": "Body — kalimat 5", "script": "Cocok untuk yang emang masih awam dan pengen dapet pendampingan penuh."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-116', '216', 116, 'Gipsy Research', 'Reset Ritme dengan 1 Tahun Akses Penuh', 'MOFU — Consideration', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Stuck berbulan-bulan atau tahunan? 1 tahun bisa jadi reset."}, {"scene": "Body — kalimat 1", "script": "Kadang yang kamu butuhin bukan materi baru — tapi sistem yang ngerestart ritmemu."}, {"scene": "Body — kalimat 2", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu dapet akses penuh ke seluruh tools dan pendampingan."}, {"scene": "Body — kalimat 3", "script": "Mulai dari evaluasi apa yang udah kamu punya, sampe nyusun ulang rencana."}, {"scene": "Body — kalimat 4", "script": "Review Mentor juga bisa bantu kamu reset arah tanpa harus restart dari nol."}, {"scene": "Body — kalimat 5", "script": "Jadi stuck yang lama bukan vonis — bisa jadi awal baru."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-117', '217', 117, 'Gipsy Research', 'Anti-Joki: 1 Tahun untuk Belajar, Bukan Instan', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Skripsi yang bagus itu yang diproses dengan waktu, bukan yang instant."}, {"scene": "Body — kalimat 1", "script": "Tapi sayangnya, banyak “solusi” instan yang nawarin jalan pintas."}, {"scene": "Body — kalimat 2", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, pendekatannya beda: kasih waktu yang cukup, bukan shortcut."}, {"scene": "Body — kalimat 3", "script": "12 bulan buat kamu yang beneran mau pahami prosesnya."}, {"scene": "Body — kalimat 4", "script": "AI-nya cuma alat — kamu yang nulis, kamu yang analisis, kamu yang dipertanggungjawabkan."}, {"scene": "Body — kalimat 5", "script": "Karena riset yang asli butuh waktu — dan itu yang Gipsy hormati."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-118', '218', 118, 'Gipsy Research', 'Komitmen Jangka Panjang 1 Tahun dengan Sistem', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Ngerjain skripsi itu komitmen jangka panjang. Bukan sprint 1-2 bulan."}, {"scene": "Body — kalimat 1", "script": "Yang keliatan “rajin” di awal biasanya burnout di tengah. Yang bertahan biasanya yang punya sistem."}, {"scene": "Body — kalimat 2", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu dapet sistem yang bisa kamu andelin selama 12 bulan."}, {"scene": "Body — kalimat 3", "script": "Mulai dari AI tools, video, worksheet, 100 Langkah, sampe review mentor."}, {"scene": "Body — kalimat 4", "script": "Tiap hari kamu bisa akses — tanpa harus ngebut marathon."}, {"scene": "Body — kalimat 5", "script": "Jadi komitmen kamu bisa dipertahankan — karena sistemnya mendukung ritme kamu."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-119', '219', 119, 'Gipsy Research', '1 Tahun untuk yang Siap Serius', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Kalau kamu udah siap serius, 1 tahun itu waktu yang ideal."}, {"scene": "Body — kalimat 1", "script": "Buat yang udah coba beberapa kali tapi belum konsisten."}, {"scene": "Body — kalimat 2", "script": "Buat yang akhirnya sadar skripsi itu emang butuh waktu dan sistem."}, {"scene": "Body — kalimat 3", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu dapet keduanya."}, {"scene": "Body — kalimat 4", "script": "Waktu yang cukup plus sistem yang ngarahin."}, {"scene": "Body — kalimat 5", "script": "Jadi kalau kamu udah siap, ini bisa jadi awal yang kamu butuhin."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned'),
  ('lib-gipsy-research-100langkah-120', '220', 120, 'Gipsy Research', '1 Tahun Sistem Penuh buat Komitmen yang Real', 'BOFU — Conversion', 'Tolong buat video sesuai dengan USP yang sudah ditentukan dan Gipsy sudah menyiapkan konten referensi. Konten referensi dari Gipsy bisa dijadikan acuan untuk membuat konten, dan konten referensi bisa disesuaikan kembali asal konteks goals dari konten gipsy tercapai. Jika ada yang ingin ditanyakan, bisa menghubungi PIC (Bagas)', 'Klik di sini untuk brand guideline', 'FREELANCE2026', '[{"scene": "Hook", "script": "Skripsi itu nggak nunggu kamu siap. Dia jalan terus, mau kamu siap apa nggak."}, {"scene": "Body — kalimat 1", "script": "Tahun ini bisa jadi tahun yang kamu mulai serius — atau bukan."}, {"scene": "Body — kalimat 2", "script": "Lewat langganan 1 tahun GipsyAI + 100 Langkah, kamu punya waktu setahun buat komitmen yang real."}, {"scene": "Body — kalimat 3", "script": "12 bulan dengan sistem yang nemenin kamu terus."}, {"scene": "Body — kalimat 4", "script": "Tiap hari, kamu bisa akses, belajar, dan eksekusi."}, {"scene": "Body — kalimat 5", "script": "Kalau bukan tahun ini, kapan? — Ini bisa jadi awal mulainya."}, {"scene": "CTA", "script": "Cek di Instagram Gipsy Research atau komen “mau” nanti aku kirim linknya."}]'::jsonb, NULL, 'unassigned');

